284	
285	    HcclHostBarrier(ctx.comm, ctx.stream);
286	
287	    AllgatherGetAsyncMulticoreKernel<<<nRanks, nullptr, ctx.stream>>>(
288	        dataBuf, nRanks, ctx.deviceCtx, (uint8_t*)sdmaMgr.GetWorkspaceAddr(), 0);
289	    ctx.aclStatus = aclrtSynchronizeStream(ctx.stream);
290	
291	    HcclHostBarrier(ctx.comm, ctx.stream);
292	    aclrtMemcpy(recvHost, recvElems * sizeof(int32_t), recvBuf, recvElems * sizeof(int32_t), ACL_MEMCPY_DEVICE_TO_HOST);
293	
294	    bool ok = VerifyAllgather(recvHost, nRanks, ELEM_COUNT, rankId, "TGET_ASYNC_MC");
295	    if (ok)
296	        PrintSample(recvHost, nRanks, ELEM_COUNT, rankId, "TGET_ASYNC_MC");
297	
298	    aclrtFreeHost(sendHost);
299	    aclrtFreeHost(recvHost);
300	    sdmaMgr.Finalize();
301	    return ctx.Finalize() && ok;
302	}
303	
304	bool RunAllgatherGetAsyncMC(int nRanks, int firstRankId, int firstDeviceId)
305	{
306	    return ForkAndRunWithHcclRootInfo(
307	        nRanks, firstRankId, firstDeviceId, [&](int rankId, const HcclRootInfo* rootInfo) {
308	            return RunAllgatherGetAsyncMCKernel(rankId, nRanks, nRanks, firstDeviceId, rootInfo);
309	        });
310	}
311	
312	// ============================================================================
313	// Ring AllGather Round Kernel (TPUT_ASYNC)
314	//
315	// Ring algorithm: N-1 rounds for N ranks.
316	//   Round 0: rank i copies sendBuf -> recvBuf[i] (local), then pushes
317	//            sendBuf -> rank (i+1)'s recvBuf[i] via TPUT_ASYNC.
318	//   Round r: rank i pushes recvBuf[chunk] -> rank (i+1)'s recvBuf[chunk]
319	//            where chunk = (i - r + N) % N.
320	//
321	// Each round is a separate kernel launch. Host-side barrier between rounds
322	// ensures all SDMA writes complete before the next round begins.
323	// ============================================================================
324	__global__ AICORE void RingAllgatherRoundKernel(
325	    __gm__ int32_t* dataBuf, int nranks, __gm__ CommDeviceContext* hcclCtx, __gm__ uint8_t* sdmaWorkspace,
326	    uint32_t sdmaSyncId, int elemCount, int round)
327	{
328	    if (nranks < 2)
329	        return;
330	
331	    int myRank = static_cast<int>(hcclCtx->rankId);
332	    int nextRank = (myRank + 1) % nranks;
333	
334	    __gm__ int32_t* sendBuf = dataBuf;
335	    __gm__ int32_t* recvBuf = dataBuf + elemCount;
336	
337	    ShapeDyn shape(1, 1, 1, 1, elemCount);
338	    StrideDyn stride(elemCount, elemCount, elemCount, elemCount, 1);
339	
340	    if (round == 0) {
341	        LocalTile tile(1, ELEM_COUNT);
342	        TASSIGN(tile, 0x10000);
343	        int chunkSize = static_cast<int>(ELEM_COUNT);
344	        int numChunks = (elemCount + chunkSize - 1) / chunkSize;
345	        ShapeDyn cShape(1, 1, 1, 1, chunkSize);
346	        StrideDyn cStride(chunkSize, chunkSize, chunkSize, chunkSize, 1);
347	        for (int c = 0; c < numChunks; ++c) {
348	            int off = c * chunkSize;
349	            GlobalI32 srcC(sendBuf + off, cShape, cStride);
350	            GlobalI32 dstC(recvBuf + myRank * elemCount + off, cShape, cStride);
351	            TLOAD(tile, srcC);
352	            set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
353	            wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
354	            TSTORE(dstC, tile);
355	            set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
356	            wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
357	        }
358	        pipe_barrier(PIPE_ALL);
359	    }
360	
361	    int sendChunkIdx = (myRank - round + nranks) % nranks;
362	    __gm__ int32_t* srcPtr = (round == 0) ? sendBuf : (recvBuf + sendChunkIdx * elemCount);
363	    __gm__ int32_t* remoteDst = CommRemotePtr(hcclCtx, recvBuf, nextRank) + sendChunkIdx * elemCount;
364	
365	    GlobalI32 srcG(srcPtr, shape, stride);
366	    GlobalI32 remoteDstG(remoteDst, shape, stride);
367	
368	    ScratchTile scratchTile;
369	    TASSIGN(scratchTile, 0x0);
370	    pto::comm::AsyncSession session;
371	    if (!pto::comm::BuildAsyncSession(scratchTile, sdmaWorkspace, session, sdmaSyncId)) {
372	        pipe_barrier(PIPE_ALL);
373	        return;
374	    }
375	
376	    pto::comm::AsyncEvent event = pto::comm::TPUT_ASYNC(remoteDstG, srcG, session);
377	    (void)event.Wait(session);
378	
379	    pipe_barrier(PIPE_ALL);
380	}
381	
382	// ============================================================================
383	// RunAllgatherRing — Ring allgather host runner
384	// ============================================================================
385	static bool RunAllgatherRingKernel(
386	    int rankId, int nRanks, int nDevices, int firstDeviceId, const HcclRootInfo* rootInfo)
387	{
388	    TestContext ctx;
389	    if (!ctx.Init(rankId, nRanks, nDevices, firstDeviceId, rootInfo))
390	        return false;
391	
392	    const size_t recvElems = static_cast<size_t>(nRanks) * ELEM_COUNT;
393	
394	    int32_t* sendHost = nullptr;
395	    int32_t* recvHost = nullptr;
396	    aclrtMallocHost(reinterpret_cast<void**>(&sendHost), ELEM_COUNT * sizeof(int32_t));
397	    aclrtMallocHost(reinterpret_cast<void**>(&recvHost), recvElems * sizeof(int32_t));
398	
399	    for (size_t i = 0; i < ELEM_COUNT; ++i)
400	        sendHost[i] = static_cast<int32_t>(rankId) * RANK_BASE + static_cast<int32_t>(i);
401	    for (size_t i = 0; i < recvElems; ++i)
402	        recvHost[i] = -1;
403	
404	    uint64_t winBase = ctx.hostCtx.windowsIn[rankId];
405	    size_t winOff = 0;
406	    size_t winBytes = SYNC_BUF_BYTES + (ELEM_COUNT + recvElems) * sizeof(int32_t);
407	    void* commPtr = WindowAlloc(winBase, winOff, winBytes);
408	
409	    int32_t* dataBuf = reinterpret_cast<int32_t*>(reinterpret_cast<uint8_t*>(commPtr) + SYNC_BUF_BYTES);
410	    int32_t* sendBuf = dataBuf;
411	    int32_t* recvBuf = dataBuf + ELEM_COUNT;
412	
413	    aclrtMemcpy(
414	        sendBuf, ELEM_COUNT * sizeof(int32_t), sendHost, ELEM_COUNT * sizeof(int32_t), ACL_MEMCPY_HOST_TO_DEVICE);
415	    aclrtMemcpy(recvBuf, recvElems * sizeof(int32_t), recvHost, recvElems * sizeof(int32_t), ACL_MEMCPY_HOST_TO_DEVICE);
416	
417	    SdmaWorkspaceManager sdmaMgr;
418	    if (!sdmaMgr.Init()) {
419	        std::cerr << "[ERROR] SdmaWorkspaceManager Init failed" << std::endl;
420	        return false;
421	    }
422	
423	    HcclHostBarrier(ctx.comm, ctx.stream);
424	
425	    int numRounds = nRanks - 1;
426	    for (int r = 0; r < numRounds; ++r) {
427	        RingAllgatherRoundKernel<<<1, nullptr, ctx.stream>>>(
428	            dataBuf, nRanks, ctx.deviceCtx, (uint8_t*)sdmaMgr.GetWorkspaceAddr(), 0, static_cast<int>(ELEM_COUNT), r);
429	        ctx.aclStatus = aclrtSynchronizeStream(ctx.stream);
430	        HcclHostBarrier(ctx.comm, ctx.stream);
431	    }
432	
433	    aclrtMemcpy(recvHost, recvElems * sizeof(int32_t), recvBuf, recvElems * sizeof(int32_t), ACL_MEMCPY_DEVICE_TO_HOST);
434	
435	    bool ok = VerifyAllgather(recvHost, nRanks, ELEM_COUNT, rankId, "RING_TPUT_ASYNC");
436	    if (ok)
437	        PrintSample(recvHost, nRanks, ELEM_COUNT, rankId, "RING_TPUT_ASYNC");
438	
439	    aclrtFreeHost(sendHost);
440	    aclrtFreeHost(recvHost);
441	    sdmaMgr.Finalize();
442	    return ctx.Finalize() && ok;
443	}
444	
445	bool RunAllgatherRing(int nRanks, int firstRankId, int firstDeviceId)
446	{
447	    return ForkAndRunWithHcclRootInfo(
448	        nRanks, firstRankId, firstDeviceId, [&](int rankId, const HcclRootInfo* rootInfo) {
449	            return RunAllgatherRingKernel(rankId, nRanks, nRanks, firstDeviceId, rootInfo);
450	        });
451	}
