11	// Allgather Async Demo — URMA Engine Kernels
12	//
13	// Mirrors the 3 SDMA AllGather algorithms in allgather_kernel.cpp, replacing:
14	//   CommDeviceContext + SdmaWorkspaceManager + CommRemotePtr
15	// with:
16	//   UrmaWorkspaceManager + UrmaPeerMrBaseAddr + BuildAsyncSession<DmaEngine::URMA>
17	//
18	// On non-URMA targets (PTO_URMA_SUPPORTED not defined, i.e. __NPU_ARCH__ != 3510)
19	// the device-side URMA instructions are compiled out via #ifdef; host runners still
20	// execute but verification will fail because remote data never arrives.
21	
22	#include <cstddef>
23	#include <cstdint>
24	#include <iostream>
25	
26	#include <pto/pto-inst.hpp>
27	#include "pto/common/pto_tile.hpp"
28	#include "common.hpp"
29	#ifdef PTO_URMA_SUPPORTED
30	#include "pto/comm/async/urma/urma_async_intrin.hpp"
31	#endif
32	
33	#include "allgather_urma_kernel.h"
34	
35	// ============================================================================
36	// Constants (same as SDMA version)
37	// ============================================================================
38	static constexpr size_t ELEM_COUNT = 256;
39	static constexpr size_t kDataOffset = 64 * sizeof(int32_t);
40	static constexpr int32_t RANK_BASE = 1000;
41	
42	using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
43	using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
44	using GlobalI32 = pto::GlobalTensor<int32_t, ShapeDyn, StrideDyn, pto::Layout::ND>;
45	using LocalTile = pto::Tile<pto::TileType::Vec, int32_t, 1, ELEM_COUNT, pto::BLayout::RowMajor, -1, -1>;
46	
47	// ============================================================================
48	// Shared device-side helper: local copy sendBuf → recvBuf[myPeer]
49	// ============================================================================
50	AICORE inline void LocalCopySendToRecv(__gm__ int32_t* sendBuf, __gm__ int32_t* recvBuf, int myPeer)
51	{
52	    ShapeDyn shape(1, 1, 1, 1, ELEM_COUNT);
53	    StrideDyn stride(ELEM_COUNT, ELEM_COUNT, ELEM_COUNT, ELEM_COUNT, 1);
54	    LocalTile tile(1, ELEM_COUNT);
55	    TASSIGN(tile, 0x10000);
56	    GlobalI32 srcG(sendBuf, shape, stride);
57	    GlobalI32 dstG(recvBuf + myPeer * ELEM_COUNT, shape, stride);
58	    TLOAD(tile, srcG);
59	    set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
60	    wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
61	    TSTORE(dstG, tile);
62	    set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
63	    wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
64	}
65	
66	// ============================================================================
67	// Multi-core URMA TPUT_ASYNC AllGather
68	//
69	// Launch with <<<nRanks, nullptr, stream>>>.
70	//   block_idx == myPeer  -> local copy (sendBuf -> recvBuf[myPeer])
71	//   block_idx != myPeer  -> TPUT_ASYNC<URMA> to remote peer block_idx
72	// ============================================================================
73	__global__ AICORE void AllgatherUrmaPutMulticoreKernel(
74	    __gm__ int32_t* dataBuf, int nranks, int myPeer, __gm__ uint8_t* urmaWorkspace)
75	{
76	    if (nranks < 2)
77	        return;
78	
79	    int bid = block_idx;
80	
81	    ShapeDyn shape(1, 1, 1, 1, ELEM_COUNT);
82	    StrideDyn stride(ELEM_COUNT, ELEM_COUNT, ELEM_COUNT, ELEM_COUNT, 1);
83	
84	    __gm__ int32_t* sendBuf = dataBuf;
85	    __gm__ int32_t* recvBuf = dataBuf + ELEM_COUNT;
86	
87	    if (bid == myPeer) {
88	        LocalCopySendToRecv(sendBuf, recvBuf, myPeer);
89	    } else {
90	#ifdef PTO_URMA_SUPPORTED
91	        int target = bid;
92	        GlobalI32 sendG(sendBuf, shape, stride);
93	        uint64_t peerBase = pto::comm::urma::UrmaPeerMrBaseAddr(urmaWorkspace, static_cast<uint32_t>(target));
94	        __gm__ int32_t* remoteSlot =
95	            reinterpret_cast<__gm__ int32_t*>(peerBase + kDataOffset) + ELEM_COUNT + myPeer * ELEM_COUNT;
96	        GlobalI32 remoteG(remoteSlot, shape, stride);
97	
98	        pto::comm::AsyncSession session;
99	        pto::comm::BuildAsyncSession<pto::comm::DmaEngine::URMA>(urmaWorkspace, static_cast<uint32_t>(target), session);
100	        pto::comm::AsyncEvent event = pto::comm::TPUT_ASYNC<pto::comm::DmaEngine::URMA>(remoteG, sendG, session);
101	        (void)event.Wait(session);
102	#endif
103	    }
104	
105	    pipe_barrier(PIPE_ALL);
106	}
107	
108	// ============================================================================
109	// Multi-core URMA TGET_ASYNC AllGather
110	//
111	// Launch with <<<nRanks, nullptr, stream>>>.
112	//   block_idx == myPeer  -> local copy
113	//   block_idx != myPeer  -> TGET_ASYNC<URMA> from remote peer block_idx
114	// ============================================================================
115	__global__ AICORE void AllgatherUrmaGetMulticoreKernel(
116	    __gm__ int32_t* dataBuf, int nranks, int myPeer, __gm__ uint8_t* urmaWorkspace)
117	{
118	    if (nranks < 2)
119	        return;
120	
121	    int bid = block_idx;
122	
123	    ShapeDyn shape(1, 1, 1, 1, ELEM_COUNT);
124	    StrideDyn stride(ELEM_COUNT, ELEM_COUNT, ELEM_COUNT, ELEM_COUNT, 1);
125	
126	    __gm__ int32_t* sendBuf = dataBuf;
127	    __gm__ int32_t* recvBuf = dataBuf + ELEM_COUNT;
128	
129	    if (bid == myPeer) {
130	        LocalCopySendToRecv(sendBuf, recvBuf, myPeer);
131	    } else {
132	#ifdef PTO_URMA_SUPPORTED
133	        int srcPeer = bid;
134	        uint64_t peerBase = pto::comm::urma::UrmaPeerMrBaseAddr(urmaWorkspace, static_cast<uint32_t>(srcPeer));
135	        __gm__ int32_t* remoteSend = reinterpret_cast<__gm__ int32_t*>(peerBase + kDataOffset);
136	        GlobalI32 remoteG(remoteSend, shape, stride);
137	        GlobalI32 localG(recvBuf + srcPeer * ELEM_COUNT, shape, stride);
138	
139	        pto::comm::AsyncSession session;
140	        pto::comm::BuildAsyncSession<pto::comm::DmaEngine::URMA>(
141	            urmaWorkspace, static_cast<uint32_t>(srcPeer), session);
142	        pto::comm::AsyncEvent event = pto::comm::TGET_ASYNC<pto::comm::DmaEngine::URMA>(localG, remoteG, session);
143	        (void)event.Wait(session);
144	#endif
145	    }
146	
147	    pipe_barrier(PIPE_ALL);
148	}
149	
150	// ============================================================================
151	// Ring URMA TPUT_ASYNC AllGather — per-round kernel
152	//
153	// Same ring algorithm as SDMA version, using TPUT_ASYNC<DmaEngine::URMA>.
154	//   round 0: local copy sendBuf → recvBuf[myPeer], then TPUT sendBuf → next peer
155	//   round r (r>=1): TPUT recvBuf[chunk] → next peer (forwarding received data)
156	// ============================================================================
157	__global__ AICORE void RingUrmaAllgatherRoundKernel(
158	    __gm__ int32_t* dataBuf, int nranks, int myPeer, __gm__ uint8_t* urmaWorkspace, int elemCount, int round)
159	{
160	    if (nranks < 2)
161	        return;
162	
163	    int nextPeer = (myPeer + 1) % nranks;
164	
165	    __gm__ int32_t* sendBuf = dataBuf;
166	    __gm__ int32_t* recvBuf = dataBuf + elemCount;
167	
168	    ShapeDyn shape(1, 1, 1, 1, elemCount);
169	    StrideDyn stride(elemCount, elemCount, elemCount, elemCount, 1);
170	
171	    if (round == 0) {
172	        LocalTile tile(1, ELEM_COUNT);
173	        TASSIGN(tile, 0x10000);
174	        int chunkSize = static_cast<int>(ELEM_COUNT);
175	        int numChunks = (elemCount + chunkSize - 1) / chunkSize;
176	        ShapeDyn cShape(1, 1, 1, 1, chunkSize);
177	        StrideDyn cStride(chunkSize, chunkSize, chunkSize, chunkSize, 1);
178	        for (int c = 0; c < numChunks; ++c) {
179	            int off = c * chunkSize;
180	            GlobalI32 srcC(sendBuf + off, cShape, cStride);
181	            GlobalI32 dstC(recvBuf + myPeer * elemCount + off, cShape, cStride);
182	            TLOAD(tile, srcC);
183	            set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
184	            wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
185	            TSTORE(dstC, tile);
186	            set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
187	            wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
188	        }
189	        pipe_barrier(PIPE_ALL);
190	    }
191	
192	    int sendChunkIdx = (myPeer - round + nranks) % nranks;
193	    __gm__ int32_t* srcPtr = (round == 0) ? sendBuf : (recvBuf + sendChunkIdx * elemCount);
194	
195	#ifdef PTO_URMA_SUPPORTED
196	    uint64_t nextBase = pto::comm::urma::UrmaPeerMrBaseAddr(urmaWorkspace, static_cast<uint32_t>(nextPeer));
197	    __gm__ int32_t* remoteDst =
198	        reinterpret_cast<__gm__ int32_t*>(nextBase + kDataOffset) + elemCount + sendChunkIdx * elemCount;
199	
200	    GlobalI32 srcG(srcPtr, shape, stride);
201	    GlobalI32 remoteDstG(remoteDst, shape, stride);
202	
203	    pto::comm::AsyncSession session;
204	    pto::comm::BuildAsyncSession<pto::comm::DmaEngine::URMA>(urmaWorkspace, static_cast<uint32_t>(nextPeer), session);
205	    pto::comm::AsyncEvent event = pto::comm::TPUT_ASYNC<pto::comm::DmaEngine::URMA>(remoteDstG, srcG, session);
206	    (void)event.Wait(session);
207	#endif
208	
209	    pipe_barrier(PIPE_ALL);
210	}
211	
212	// ============================================================================
213	// Host-side helpers (same logic as SDMA version)
214	// ============================================================================
215	static bool VerifyAllgather(const int32_t* host, int nRanks, size_t elemCount, int rankId, const char* tag)
216	{
217	    for (int r = 0; r < nRanks; ++r) {
218	        for (size_t i = 0; i < elemCount; ++i) {
219	            int32_t expected = static_cast<int32_t>(r) * RANK_BASE + static_cast<int32_t>(i);
220	            int32_t actual = host[r * elemCount + i];
221	            if (actual != expected) {
222	                std::cerr << "[" << tag << " FAIL] Rank " << rankId << ": recvBuf[" << r << "][" << i
223	                          << "] = " << actual << ", expected " << expected << std::endl;
224	                return false;
225	            }
226	        }
227	    }
228	    return true;
229	}
230	
231	static void PrintSample(const int32_t* host, int nRanks, size_t elemCount, int rankId, const char* tag)
232	{
233	    int mpiSize = CommMpiSize();
234	    for (int r = 0; r < mpiSize; ++r) {
235	        if (r == CommMpiRank()) {
236	            std::cout << "[" << tag << " PASS] Rank " << rankId << ": ";
237	            for (int s = 0; s < nRanks && s < 3; ++s) {
238	                std::cout << "slot[" << s << "]=[";
239	                for (size_t i = 0; i < 3 && i < elemCount; ++i)
240	                    std::cout << (i ? "," : "") << host[s * elemCount + i];
241	                std::cout << ",...] ";
242	            }
243	            if (nRanks > 3)
244	                std::cout << "...";
245	            std::cout << std::endl;
246	            std::cout.flush();
247	        }
248	        CommMpiBarrier();
249	    }
250	}
251	
252	// ============================================================================
253	// Host-side runner context — common init / data-prep / verify / cleanup
254	// ============================================================================
255	struct UrmaRunnerEnv {
256	    UrmaTestContext ctx;
257	    int32_t* sendHost = nullptr;
258	    int32_t* recvHost = nullptr;
259	    int32_t* dataBuf = nullptr;
260	    int32_t* sendBuf = nullptr;
261	    int32_t* recvBuf = nullptr;
262	    int myPeer = 0;
263	    size_t recvElems = 0;
264	
265	    bool Init(int rankId, int nRanks, int nDevices, int firstDeviceId, int firstRankId, int rootRank)
266	    {
267	        myPeer = rankId - firstRankId;
268	        recvElems = static_cast<size_t>(nRanks) * ELEM_COUNT;
269	        size_t commBytesNeeded = kDataOffset + (ELEM_COUNT + recvElems) * sizeof(int32_t);
270	
271	        if (!ctx.Setup(rankId, nRanks, nDevices, firstDeviceId, rootRank, commBytesNeeded))
272	            return false;
273	
274	        aclrtMallocHost(reinterpret_cast<void**>(&sendHost), ELEM_COUNT * sizeof(int32_t));
275	        aclrtMallocHost(reinterpret_cast<void**>(&recvHost), recvElems * sizeof(int32_t));
276	
277	        for (size_t i = 0; i < ELEM_COUNT; ++i)
278	            sendHost[i] = static_cast<int32_t>(myPeer) * RANK_BASE + static_cast<int32_t>(i);
279	        for (size_t i = 0; i < recvElems; ++i)
280	            recvHost[i] = -1;
281	
282	        dataBuf = reinterpret_cast<int32_t*>(reinterpret_cast<uint8_t*>(ctx.devBuf) + kDataOffset);
283	        sendBuf = dataBuf;
284	        recvBuf = dataBuf + ELEM_COUNT;
285	
286	        aclrtMemcpy(
287	            sendBuf, ELEM_COUNT * sizeof(int32_t), sendHost, ELEM_COUNT * sizeof(int32_t), ACL_MEMCPY_HOST_TO_DEVICE);
288	        aclrtMemcpy(
289	            recvBuf, recvElems * sizeof(int32_t), recvHost, recvElems * sizeof(int32_t), ACL_MEMCPY_HOST_TO_DEVICE);
290	
291	        CommMpiBarrier();
292	        return true;
293	    }
294	
295	    bool VerifyAndReport(int nRanks, int rankId, const char* tag)
296	    {
297	        aclrtMemcpy(
298	            recvHost, recvElems * sizeof(int32_t), recvBuf, recvElems * sizeof(int32_t), ACL_MEMCPY_DEVICE_TO_HOST);
299	        bool ok = VerifyAllgather(recvHost, nRanks, ELEM_COUNT, rankId, tag);
300	        if (ok)
301	            PrintSample(recvHost, nRanks, ELEM_COUNT, rankId, tag);
302	        return ok;
303	    }
304	
305	    void Cleanup()
306	    {
307	        aclrtFreeHost(sendHost);
308	        aclrtFreeHost(recvHost);
309	        ctx.Cleanup();
310	    }
311	};
312	
313	// ============================================================================
314	// Host-side runners
315	// ============================================================================
316	static bool RunAllgatherUrmaPutMCKernel(
317	    int rankId, int nRanks, int nDevices, int firstDeviceId, int firstRankId, int rootRank)
318	{
319	    UrmaRunnerEnv env;
320	    if (!env.Init(rankId, nRanks, nDevices, firstDeviceId, firstRankId, rootRank))
321	        return false;
322	
323	    AllgatherUrmaPutMulticoreKernel<<<nRanks, nullptr, env.ctx.stream>>>(
324	        env.dataBuf, nRanks, env.myPeer, reinterpret_cast<uint8_t*>(env.ctx.urmaMgr.GetWorkspaceAddr()));
325	    aclrtSynchronizeStream(env.ctx.stream);
326	    CommMpiBarrier();
327	
328	    bool ok = env.VerifyAndReport(nRanks, rankId, "URMA_TPUT_MC");
329	    env.Cleanup();
330	    return ok;
331	}
332	
333	static bool RunAllgatherUrmaGetMCKernel(
334	    int rankId, int nRanks, int nDevices, int firstDeviceId, int firstRankId, int rootRank)
335	{
336	    UrmaRunnerEnv env;
337	    if (!env.Init(rankId, nRanks, nDevices, firstDeviceId, firstRankId, rootRank))
338	        return false;
339	
340	    AllgatherUrmaGetMulticoreKernel<<<nRanks, nullptr, env.ctx.stream>>>(
341	        env.dataBuf, nRanks, env.myPeer, reinterpret_cast<uint8_t*>(env.ctx.urmaMgr.GetWorkspaceAddr()));
342	    aclrtSynchronizeStream(env.ctx.stream);
343	    CommMpiBarrier();
344	
345	    bool ok = env.VerifyAndReport(nRanks, rankId, "URMA_TGET_MC");
346	    env.Cleanup();
347	    return ok;
348	}
349	
350	static bool RunAllgatherUrmaRingKernel(
351	    int rankId, int nRanks, int nDevices, int firstDeviceId, int firstRankId, int rootRank)
352	{
353	    UrmaRunnerEnv env;
354	    if (!env.Init(rankId, nRanks, nDevices, firstDeviceId, firstRankId, rootRank))
355	        return false;
356	
357	    int numRounds = nRanks - 1;
358	    for (int r = 0; r < numRounds; ++r) {
359	        RingUrmaAllgatherRoundKernel<<<1, nullptr, env.ctx.stream>>>(
360	            env.dataBuf, nRanks, env.myPeer, reinterpret_cast<uint8_t*>(env.ctx.urmaMgr.GetWorkspaceAddr()),
361	            static_cast<int>(ELEM_COUNT), r);
362	        aclrtSynchronizeStream(env.ctx.stream);
363	        CommMpiBarrier();
364	    }
365	
366	    bool ok = env.VerifyAndReport(nRanks, rankId, "URMA_RING_TPUT");
367	    env.Cleanup();
368	    return ok;
369	}
370	
371	// ============================================================================
372	// Public API
373	// ============================================================================
374	bool RunAllgatherUrmaPutMC(int nRanks, int nDevices, int firstRankId, int firstDeviceId)
375	{
376	    return RunUrmaTestMpiLaunch(nRanks, nDevices, firstRankId, firstDeviceId, RunAllgatherUrmaPutMCKernel);
377	}
378	
379	bool RunAllgatherUrmaGetMC(int nRanks, int nDevices, int firstRankId, int firstDeviceId)
380	{
381	    return RunUrmaTestMpiLaunch(nRanks, nDevices, firstRankId, firstDeviceId, RunAllgatherUrmaGetMCKernel);
382	}
383	
384	bool RunAllgatherUrmaRing(int nRanks, int nDevices, int firstRankId, int firstDeviceId)
385	{
386	    return RunUrmaTestMpiLaunch(nRanks, nDevices, firstRankId, firstDeviceId, RunAllgatherUrmaRingKernel);
387	}
