// ============================================================================

enum class DmaEngine : uint8_t {
    SDMA = 0, // Supports 2D transfer
    URMA = 1, // Supports 1D transfer (HCCP V2 Jetty, NPU_ARCH 3510 only)
    RDMA = 2, // RDMA engine; RdmaBackend identifies the NIC implementation compiled into the binary
};

// ============================================================================
// CollEngine: Backend engine selector for collective instructions
//   AIV  — default tile-based path (TLOAD + compute + TSTORE)
//   CCU  — AIV triggers CKE gate, CCU hardware performs the collective
// ============================================================================

enum class CollEngine : uint8_t {
    AIV = 0,
    CCU = 1,
};

// ============================================================================
// CcuInputSource: Selects who is responsible for writing the CCU input HBM.
//
//   HostManaged — Host (e.g. aclrtMemcpy / a prior op) has already populated
//                 parallelGroup[selfIdx]; the AIV trigger kernel only doorbells
//                 the CKE gate. accTileData / recvTileData are not consumed by
//                 the CCU IMPL. This is the legacy behaviour.
//
//   AivStored  — The AIV trigger kernel carries this rank's partial in
//                accTileData. The CCU IMPL TSTOREs it into
//                parallelGroup[selfIdx] (== host-registered inputAddr VA),
//                pipe_barrier(PIPE_MTE3)s, then doorbells. This enables
//                AIV-fused collectives: previous AIV stage → accTile →
//                CCU reduce → outputAddr, all without host memcpy.
// ============================================================================

enum class CcuInputSource : uint8_t {
    HostManaged = 0,
    AivStored = 1,
};

// ============================================================================
// CcuTriggerContext: Opaque context passed from host to AIV kernel for CCU path.
// Host fills it from ccu::TryGet() + rtGetDevResAddress() before kernel launch.
// ============================================================================

struct CcuTriggerContext {
    uint64_t ckeSlotVA{0};                                   // CKE slot VA from rtGetDevResAddress(dieId, ckeId)
    uint32_t mask{0};                                        // 16-bit CKE trigger mask
    uint32_t selfIdx{0};                                     // This rank's index inside the ParallelGroup
    CcuInputSource inputSource{CcuInputSource::HostManaged}; // Who fills CCU's input HBM
};

// ============================================================================
// AsyncEvent: Returned by TPUT_ASYNC / TGET_ASYNC for asynchronous DMA
// ============================================================================

struct AsyncSession;

struct AsyncEvent {
    uint64_t handle{0};
    DmaEngine engine{DmaEngine::SDMA};
    uint32_t urmaTargetCqe{0};

    AICORE constexpr AsyncEvent() = default;
    AICORE constexpr AsyncEvent(uint64_t h, DmaEngine e, uint32_t targetCqe = 0U)
        : handle(h), engine(e), urmaTargetCqe(targetCqe)
    {}
    AICORE constexpr bool valid() const { return handle != 0U; }

    PTO_INTERNAL bool Wait(const AsyncSession& session) const;
    PTO_INTERNAL bool Test(const AsyncSession& session) const;
};

// ============================================================================
// Signal: Scalar signal (1 element, fully static)
//
// Equivalent to:
//   GlobalTensor<int32_t, Shape<1,1,1,1,1>, Stride<1,1,1,1,1>, Layout::ND>
//
// Usage:
//   comm::Signal sig(ptr);
// ============================================================================

using Signal = GlobalTensor<int32_t, Shape<1, 1, 1, 1, 1>, Stride<1, 1, 1, 1, 1>, Layout::ND>;

// GlobalSignal: alias for GlobalTensor, used by signal-related instructions
template <typename Element_, typename Shape_, typename Stride_, Layout Layout_ = Layout::ND>
using GlobalSignal = GlobalTensor<Element_, Shape_, Stride_, Layout_>;

// ============================================================================
// Signal2D: 2D signal matrix with compile-time shape
//
// Dense case:     stride auto-derived from shape (DIM_3 stride = Cols).
// Sub-region:     pass a custom stride for views into a larger signal grid.
//
// Usage:
//   // Dense 4x8 grid (stride auto = 8)
//   comm::Signal2D<4, 8> grid(ptr);
//
//   // Sub-region 4x8 from a 128-col grid (stride = 128)
//   comm::Signal2D<4, 8> sub(ptr + offset, 128);
// ============================================================================

template <int Rows, int Cols>
struct Signal2D : public GlobalTensor<int32_t, Shape<1, 1, 1, Rows, Cols>, Stride<1, 1, 1, DYNAMIC, 1>, Layout::ND> {
private:
    using Base = GlobalTensor<int32_t, Shape<1, 1, 1, Rows, Cols>, Stride<1, 1, 1, DYNAMIC, 1>, Layout::ND>;

public:
    // Dense constructor: stride = Cols (contiguous layout)
    PTO_INTERNAL Signal2D(typename Base::DType* ptr) : Base(ptr, typename Base::Shape{}, typename Base::Stride{Cols}) {}

    // Strided constructor: custom DIM_3 stride for sub-region views
    PTO_INTERNAL Signal2D(typename Base::DType* ptr, int stride)
        : Base(ptr, typename Base::Shape{}, typename Base::Stride{stride})
    {}
};

} // namespace comm
} // namespace pto

