20	
21	// A5 keeps DmaEngine::SDMA as an API-compatible name for the synchronous MTE
22	// fallback. Complete every payload chunk before issuing the Scalar notification,
23	// then return handle 0 to represent an already-completed operation.
24	//
25	// Intended ordering and concurrency semantics:
26	// - Repeated calls from one AICore are fully serialized.
27	// - AtomicAdd to one signal may aggregate completions from multiple AICores or
28	//   ranks, provided every payload uses a non-conflicting destination range.
29	// - Set does not define a winner when multiple AICores or ranks write one signal;
30	//   use one signal slot per producer or AtomicAdd for completion counting.
31	// Receiver-side visibility and multi-producer cases require dedicated hardware
32	// stress tests; the current ST covers sequential calls from one sender AICore.
33	template <typename GlobalDstData, typename GlobalSrcData, typename GlobalSignalData>
34	PTO_INTERNAL AsyncEvent TPUT_ASYNC_NOTIFY_MTE_FALLBACK(
35	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, GlobalSignalData& dstSignalData, int32_t signalValue,
36	    NotifyOp notifyOp, const AsyncSession& session)
37	{
38	    PTO_ASSERT(
39	        session.valid && session.engine == DmaEngine::SDMA,
40	        "TPUT_ASYNC_NOTIFY: A5 MTE fallback requires a valid SDMA session.");
41	    TPutAsyncValidateNotifySignal(dstSignalData, notifyOp);
42	
43	    // TPUT_ASYNC_MTE_FALLBACK uses MTE3 -> MTE2 events for UB reuse. Ensure the
44	    // payload reaches DDR, then order all pipelines before the Scalar notification.
45	    (void)TPUT_ASYNC_MTE_FALLBACK(dstGlobalData, srcGlobalData, session);
46	    dsb(DSB_DDR);
47	    pipe_barrier(PIPE_ALL);
48	    TNOTIFY_IMPL(dstSignalData, signalValue, notifyOp);
49	    return AsyncEvent(0, DmaEngine::SDMA);
50	}
51	
52	#ifdef PTO_URMA_SUPPORTED
53	template <typename GlobalDstData, typename GlobalSrcData, typename GlobalSignalData>
54	PTO_INTERNAL AsyncEvent TPUT_ASYNC_NOTIFY_URMA(
55	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, GlobalSignalData& dstSignalData, int32_t signalValue,
56	    NotifyOp notifyOp, const AsyncSession& session, uint32_t peer)
57	{
58	    const uint64_t transferSize = TPutAsyncCheckUrmaPayload(dstGlobalData, srcGlobalData, session, peer);
59	    TPutAsyncValidateNotifySignal(dstSignalData, notifyOp);
60	
61	    const urma::detail::UrmaPostResult result = urma::__urma_put_async_notify(
62	        reinterpret_cast<__gm__ uint8_t*>(dstGlobalData.data()),
63	        reinterpret_cast<__gm__ uint8_t*>(srcGlobalData.data()), transferSize,
64	        reinterpret_cast<__gm__ int32_t*>(dstSignalData.data()), signalValue, notifyOp, session, peer);
65	    return AsyncEvent(result.handle, DmaEngine::URMA, result.targetCqe);
66	}
67	#endif
68	
69	#ifdef PTO_RDMA_SUPPORTED
70	template <typename GlobalDstData, typename GlobalSrcData, typename GlobalSignalData>
71	PTO_INTERNAL AsyncEvent TPUT_ASYNC_NOTIFY_RDMA(
72	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, GlobalSignalData& dstSignalData, int32_t signalValue,
73	    NotifyOp notifyOp, const AsyncSession& session, uint32_t peer)
74	{
75	    PTO_ASSERT(
76	        session.valid && session.engine == DmaEngine::RDMA, "TPUT_ASYNC_NOTIFY: RDMA requires a valid RDMA session.");
77	    const uint64_t transferSize = TPutAsyncValidatePayload(dstGlobalData, srcGlobalData);
78	    TPutAsyncValidateNotifySignal(dstSignalData, notifyOp);
79	    if (notifyOp != NotifyOp::Set) {
80	        PTO_ASSERT(false, "TPUT_ASYNC_NOTIFY: RDMA currently supports NotifyOp::Set only.");
81	        return AsyncEvent(rdma::EncodeErrorHandle(rdma::kRdmaUnsupportedOperationError), DmaEngine::RDMA);
82	    }
83	    PTO_ASSERT(transferSize <= 0x7fffffffULL, "TPUT_ASYNC_NOTIFY: RDMA payload must not exceed 0x7fffffff bytes.");
84	
85	    const uint64_t eventHandle = rdma::WriteNotify(
86	        session, reinterpret_cast<__gm__ uint8_t*>(dstGlobalData.data()),
87	        reinterpret_cast<__gm__ uint8_t*>(srcGlobalData.data()), transferSize,
88	        reinterpret_cast<__gm__ int32_t*>(dstSignalData.data()), signalValue, peer);
89	    return AsyncEvent(eventHandle, DmaEngine::RDMA);
90	}
91	#endif
92	
93	} // namespace detail
94	
95	template <DmaEngine engine = DmaEngine::SDMA, typename GlobalDstData, typename GlobalSrcData, typename GlobalSignalData>
96	PTO_INTERNAL AsyncEvent TPUT_ASYNC_NOTIFY_IMPL(
97	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, GlobalSignalData& dstSignalData, int32_t signalValue,
98	    NotifyOp notifyOp, const AsyncSession& session, uint32_t peer)
99	{
100	    if constexpr (engine == DmaEngine::SDMA) {
101	        (void)peer;
102	        return detail::TPUT_ASYNC_NOTIFY_MTE_FALLBACK(
103	            dstGlobalData, srcGlobalData, dstSignalData, signalValue, notifyOp, session);
104	    } else if constexpr (engine == DmaEngine::URMA) {
105	#ifdef PTO_URMA_SUPPORTED
106	        return detail::TPUT_ASYNC_NOTIFY_URMA(
107	            dstGlobalData, srcGlobalData, dstSignalData, signalValue, notifyOp, session, peer);
108	#else
109	        static_assert(engine != DmaEngine::URMA, "TPUT_ASYNC_NOTIFY: A5 URMA requires NPU_ARCH 3510");
110	        return {};
111	#endif
112	    } else if constexpr (engine == DmaEngine::RDMA) {
113	#ifdef PTO_RDMA_SUPPORTED
114	        return detail::TPUT_ASYNC_NOTIFY_RDMA(
115	            dstGlobalData, srcGlobalData, dstSignalData, signalValue, notifyOp, session, peer);
116	#else
117	        static_assert(engine != DmaEngine::RDMA, "TPUT_ASYNC_NOTIFY: RDMA support is not enabled for this build");
118	        return AsyncEvent(0, engine);
119	#endif
120	    } else {
121	        static_assert(engine == DmaEngine::SDMA, "TPUT_ASYNC_NOTIFY: unsupported DMA engine");
122	        return AsyncEvent(0, engine);
123	    }
124	}
